export async function assertWorkspaceWritable(
  orgId: OrgId,
  now = new Date(),
): Promise<void> {
  const subscription = await subscriptionRepo.findSubscription(orgId);
  const reason = lockReasonFor(subscription, now);
  if (reason !== null) throw new WorkspaceLockedError(orgId, reason);
}

